import {
  getViolations,
  runAuditTool,
  createAgent,
  DEMO_HTML,
  runFixerLoop,
} from "/home/isourxbh/autoa11y/backend/fixer.js";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";

const ctx = { agentId: "test", iteration: 0 };

