function StatCard({ label, count, tone }) {
  const tones = {
    red: {
      ring: "border-red-200",
      dot: "bg-red-500",
    },
    green: {
      ring: "border-emerald-200",
      dot: "bg-emerald-500",
    },
  }[tone];

  return (
    <div className={`rounded-lg border ${tones.ring} bg-white p-5`}>
      <div className="flex items-center gap-2">
        <span className={`h-2 w-2 rounded-full ${tones.dot}`} />
        <span className="text-sm font-medium text-slate-500">{label}</span>
      </div>
      <div className="mt-2 flex items-baseline gap-2">
        <span className="text-4xl font-bold tabular-nums text-slate-900">
          {count}
        </span>
        <span className="text-sm text-slate-500">
          {count === 1 ? "violation" : "violations"}
        </span>
      </div>
    </div>
  );
}

function Arrow() {
  return (
    <div className="flex items-center justify-center px-2 text-slate-400">
      <svg
        viewBox="0 0 24 24"
        fill="none"
        stroke="currentColor"
        strokeWidth="2"
        strokeLinecap="round"
        strokeLinejoin="round"
        className="h-7 w-7"
      >
        <path d="M5 12h14" />
        <path d="m13 6 6 6-6 6" />
      </svg>
    </div>
  );
}

// __APP__

import { chromium } from "playwright";

const url = "http://localhost:5173/";
const browser = await chromium.launch();
const page = await browser.newPage();

const consoleErrors = [];
const pageErrors = [];
page.on("console", (msg) => {
  if (msg.type() === "error") consoleErrors.push(msg.text());
});
page.on("pageerror", (err) => pageErrors.push(err.message));

await page.goto(url, { waitUntil: "networkidle" });
await page.waitForTimeout(1500);

const title = await page.title();
const button = await page.getByText("Run AutoA11y Fixer").count();
const before = await page.getByText("Before", { exact: true }).count();
const after = await page.getByText("After", { exact: true }).count();
const fileName = await page.getByText("demo-site/index.html").count();

// Diff viewer rendered lines: look for elements with diff line content.
const removedLine = await page.locator("text=#cccccc").count();
const addedLine = await page.locator("text=#555555").count();
const altLine = await page.locator("text=Decorative accessibility demo graphic").count();

console.log("title:", title);
console.log("Run button count:", button);
console.log("Before label:", before, "| After label:", after);
console.log("filename:", fileName);
console.log("diff removed line (#cccccc):", removedLine);
console.log("diff added line (#555555):", addedLine);
console.log("diff added alt text:", altLine);
console.log("console errors:", consoleErrors.length);
console.log("page errors:", pageErrors.length);
if (consoleErrors.length) console.log("CONSOLE ERRORS:", consoleErrors.slice(0, 5));
if (pageErrors.length) console.log("PAGE ERRORS:", pageErrors.slice(0, 5));

await page.screenshot({ path: "/tmp/autoa11y-frontend.png", fullPage: true });
console.log("screenshot saved to /tmp/autoa11y-frontend.png");

await browser.close();

