import { getValidClineCredentials } from "@cline/sdk";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";

const providersPath = path.join(os.homedir(), ".cline", "data", "settings", "providers.json");
const data = JSON.parse(fs.readFileSync(providersPath, "utf8"));

for (const name of ["cline-pass", "cline"]) {
  const auth = data.providers[name]?.settings?.auth;
  if (!auth?.accessToken) continue;
  const now = Date.now();
  const exp = Number(auth.expiresAt) || 0;
  const before = auth.accessToken.slice(0, 14);
  console.log(`\n[${name}] expired=${exp < now} expires=${new Date(exp).toISOString()} token=${before}...`);
  const creds = {
    access: auth.accessToken,
    refresh: auth.refreshToken,
    expires: exp,
    accountId: auth.accountId,
    metadata: auth.metadata,
  };
  try {
    const valid = await getValidClineCredentials(creds, { apiBaseUrl: "https://api.cline.bot" });
    if (!valid) {
      console.log("  -> null (refresh token rejected)");
    } else {
      const changed = valid.access.slice(0, 14) !== before;
      console.log(`  -> valid, token changed=${changed}, new expires=${valid.expires ? new Date(valid.expires).toISOString() : "n/a"}`);
    }
  } catch (e) {
    console.log("  -> threw:", e.message);
  }
}

