const c = (code) => (s) => (useColor ? `\x1b[${code}m${s}\x1b[0m` : s);
const red = c("31"), green = c("32"), yellow = c("33"), cyan = c("36"), magenta = c("35"), dim = c("2"), bold = c("1");

function usage() {
  console.log(`${bold("autoa11y")} — accessibility auto-fixer CLI`);
  console.log("");
  console.log("Usage:");
  console.log("  autoa11y fix <file_path>   Fix accessibility issues in an HTML file");
  console.log("");
  console.log("Examples:");
  console.log("  autoa11y fix ./demo-site/index.html");
}

async function fixCommand(filePath) {
  const target = path.resolve(process.cwd(), filePath);
  // validate exists
  ...
  console.log(`${bold("AutoA11y fixer")}`);
  console.log(`${dim("Target:")} ${target}`);
  console.log("");

  const agent = await createAgent(target);

  // live progress
  const unsubscribe = agent.subscribe((event) => {
    if (event.type === "tool-started") {
      console.log(`${dim("  ⚙️  ")}${cyan(event.toolCall.toolName)}`);
    } else if (event.type === "turn-started") {
      console.log(`${dim("  → turn ")}${event.iteration}`);
    }
  });

  const result = await runFixerLoop(agent, { targetFile: target });
  unsubscribe();

  // colored summary
  console.log("");
  console.log(`${bold("Summary")}`);
  console.log(`  Before: ${red(String(result.initialViolations))} violation(s)`);
  console.log(`  After:  ${green(String(result.violations))} violation(s)`);
  if (result.clean) {
    console.log("");
    console.log(`${green(bold("✅ All accessibility issues fixed."))}`);
  } else {
    console.log("");
    console.log(`${yellow(bold(`⚠️  ${result.violations} violation(s) remain after ${result.iterations} iteration(s).`))}`);
    process.exitCode = 1;
  }
}

async function main() {
  const [cmd, arg] = process.argv.slice(2);
  if (cmd === "fix" && arg) {
    await fixCommand(arg);
  } else {
    usage();
    process.exitCode = 1;
  }
}

main().catch((err) => {
  console.error(`${red("error:")} ${err.message}`);
  process.exitCode = 1;
});
```

