import { chromium } from "playwright";
import { AxeBuilder } from "@axe-core/playwright";
import path from "node:path";
import { pathToFileURL } from "node:url";

// Run axe-core against a local HTML file and return a flattened array of
// violations (the same shape as the GET /audit endpoint response).
export async function auditHtmlFile(filePath) {
  const browser = await chromium.launch();
  try {
    const context = await browser.newContext();
    const page = await context.newPage();
    await page.goto(pathToFileURL(path.resolve(filePath)).href, {
      waitUntil: "load",
    });

    const results = await new AxeBuilder({ page }).analyze();

    return results.violations.map((violation) => ({
      id: violation.id,
      impact: violation.impact,
      description: violation.description,
      help: violation.help,
      helpUrl: violation.helpUrl,
      nodes: violation.nodes.map((node) => ({
        html: node.html,
        selectors: node.target,
        failureSummary: node.failureSummary,
      })),
    }));
  } finally {
    await browser.close();
  }
}

// Custom tool: run an axe-core audit against the target file so the agent can
// verify its own work.
function createRunAuditTool(targetFile) {
  return createTool({
    name: "run_audit",
    description:
      "Run the axe-core accessibility audit against the target HTML file and return the JSON array of violations. An empty array means the page passes the audit.",
    inputSchema: {
      type: "object",
      properties: {},
      additionalProperties: false,
    },
    execute: async () => {
      return await auditHtmlFile(targetFile);
    },
  });
}

