const providersPath = path.join(os.homedir(), ".cline", "data", "settings", "providers.json");
const data = JSON.parse(fs.readFileSync(providersPath, "utf8"));

for (const name of ["cline", "cline-pass"]) {
  const auth = data.providers[name]?.settings?.auth;
  if (!auth?.accessToken) continue;
  const token = auth.accessToken;
  const res = await fetch("https://api.cline.bot/api/v1/chat/completions", {
    method: "POST",
    headers: { Authorization: `Bearer ${token}`, "Content-Type": "application/json" },
    body: JSON.stringify({
      model: "cline-pass/deepseek-v4-pro",
      messages: [{ role: "user", content: "say ok" }],
      max_tokens: 8,
      stream: false,
    }),
  });
  console.log(name, "-> HTTP", res.status, "|", (await res.text()).slice(0, 120));
}

import { getValidClineCredentials } from "@cline/sdk";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";

const providersPath = path.join(os.homedir(), ".cline", "data", "settings", "providers.json");
const data = JSON.parse(fs.readFileSync(providersPath, "utf8"));
const now = Date.now();

const candidates = ["cline-pass", "cline"]
  .map((id) => ({ id, settings: data.providers?.[id]?.settings }))
  .filter((c) => c.settings?.auth?.accessToken);

const chosen = candidates.reduce((best, c) => {
  const bestExp = Number(best.settings.auth.expiresAt) || 0;
  const cExp = Number(c.settings.auth.expiresAt) || 0;
  const bestValid = bestExp > now;
  const cValid = cExp > now;
  if (cValid !== bestValid) return cValid ? c : best;
  return cExp > bestExp ? c : best;
});

console.log("chosen provider:", chosen.id);
const auth = chosen.settings.auth;
const before = auth.accessToken.slice(0, 16);

const creds = {
  access: auth.accessToken,
  refresh: auth.refreshToken,
  expires: Number(auth.expiresAt) || 0,
  accountId: auth.accountId,
  metadata: auth.metadata,
};

const valid = await getValidClineCredentials(creds, { apiBaseUrl: "https://api.cline.bot" }, { forceRefresh: (Number(auth.expiresAt) || 0) <= now });
console.log("getValidClineCredentials ->", valid ? "non-null" : "null");
if (valid) {
  console.log("  token changed:", valid.access.slice(0, 16) !== before);
  console.log("  returned token prefix:", valid.access.slice(0, 16) + "...");
  console.log("  returned expires:", valid.expires ? new Date(valid.expires).toISOString() : "n/a");

  // Test the returned token against the gateway
  const res = await fetch("https://api.cline.bot/api/v1/chat/completions", {
    method: "POST",
    headers: { Authorization: `Bearer ${valid.access}`, "Content-Type": "application/json" },
    body: JSON.stringify({
      model: "cline-pass/deepseek-v4-pro",
      messages: [{ role: "user", content: "Reply with the word: hello" }],
      max_tokens: 32,
      stream: false,
    }),
  });
  console.log("gateway with returned token -> HTTP", res.status);
  console.log("  body:", (await res.text()).slice(0, 200));
}

