import { parse } from "node-html-parser";

// Patterns the agent is not allowed to introduce (used to hide/remove content).
const HIDING_CHECKS = [
  ["aria-hidden", (el) => el.getAttribute("aria-hidden") === "true"],
  ["role=presentation/none", (el) => ["presentation", "none"].includes(el.getAttribute("role"))],
  ["display:none", (el) => (el.getAttribute("style") || "").replace(/\s/g, "").includes("display:none")],
  ["visibility:hidden", (el) => (el.getAttribute("style") || "").replace(/\s/g, "").includes("visibility:hidden")],
  ["tabindex=-1", (el) => el.getAttribute("tabindex") === "-1"],
];

function allElements(root) {
  return root.querySelectorAll("*");
}

function countTags(root) {
  const counts = {};
  for (const el of allElements(root)) {
    const tag = el.tagName.toLowerCase();
    counts[tag] = (counts[tag] || 0) + 1;
  }
  return counts;
}

function countHiding(root) {
  const counts = {};
  for (const el of allElements(root)) {
    for (const [name, check] of HIDING_CHECKS) {
      if (check(el)) counts[name] = (counts[name] || 0) + 1;
    }
  }
  return counts;
}

// Collect visible text chunks, skipping script/style content.
