  const chunks = [];
  const walk = (el) => {
    for (const child of el.childNodes) {
      if (child.nodeType === 3) {
        const t = child.text.replace(/\s+/g, " ").trim();
        if (t) chunks.push(t);
      } else if (child.tagName) {
        const tag = child.tagName.toLowerCase();
        if (tag !== "script" && tag !== "style") walk(child);
      }
    }
  };
  walk(root);
  return chunks;
}

