```js
function parseNodeString(str) {
  // str like: 'heading "ग्राम सभा सूचना बोर्ड" [level=2]' or 'img' or 'textbox'
  const m = str.match(/^(\S+)(?:\s+"([^"]*)")?(?:\s+\[([^\]]*)\])?$/);
  if (!m) return { role: str, name: null, attrs: {} };
  const role = m[1];
  const name = m[2] ?? null;
  const attrs = {};
  if (m[3]) {
    for (const part of m[3].split(",")) {
      const [k, v] = part.trim().split("=");
      attrs[k.trim()] = v !== undefined ? v.trim().replace(/^"|"$/g, "") : true;
    }
  }
  return { role, name, attrs };
}
```

