 37 |   const emit = ({ role, name, attrs }, parentRole) => {
 38 |     if (LANDMARKS.has(role)) {
 39 |       lines.push(`${role} landmark`);
 40 |     } else if (role === "heading") {
 41 |       const lvl = attrs.level ? `, level ${attrs.level}` : "";
 42 |       lines.push(`heading${lvl}, ${name || ""}`.replace(/,\s*$/, ""));
 43 |     } else if (role === "button") {
 44 |       lines.push(name ? `button, ${name}` : "button");
 45 |     } else if (role === "link") {
 46 |       lines.push(name ? `link, ${name}` : "link");
 47 |     } else if (role === "textbox") {
 48 |       lines.push(name ? `edit text, ${name}` : "edit text");
 49 |     } else if (role === "combobox") {
 50 |       lines.push(name ? `combo box, ${name}` : "combo box");
 51 |     } else if (role === "img") {
