// Parse a CSS color into { r, g, b } (0-255). Supports hex (#rgb, #rrggbb,
// #rrggbbaa) and rgb()/rgba().
export function parseColor(str) {
  const s = String(str).trim().toLowerCase();
  if (!s) throw new Error(`Invalid color: ${JSON.stringify(str)}`);

  // #rgb / #rrggbb / #rrggbbaa
  const hex = s.match(/^#([0-9a-f]{3,8})$/);
  if (hex) {
    let h = hex[1];
    if (h.length === 3 || h.length === 4) {
      h = h.split("").map((c) => c + c).join("");
    }
    const r = parseInt(h.slice(0, 2), 16);
    const g = parseInt(h.slice(2, 4), 16);
    const b = parseInt(h.slice(4, 6), 16);
    if ([r, g, b].some((n) => Number.isNaN(n))) throw new Error(`Invalid hex color: ${str}`);
    return { r, g, b };
  }

  // rgb()/rgba()
  const fn = s.match(/^rgba?\(\s*([\d.]+%?)\s*[, ]\s*([\d.]+%?)\s*[, ]\s*([\d.]+%?)\s*(?:[,/]\s*([\d.]+%?)\s*)?\)$/);
  if (fn) {
    const to255 = (v) => (v.endsWith("%") ? (parseFloat(v) / 100) * 255 : parseFloat(v));
    return { r: clamp(to255(fn[1]), 0, 255), g: clamp(to255(fn[2]), 0, 255), b: clamp(to255(fn[3]), 0, 255) };
  }

  throw new Error(`Unsupported color format: ${str}`);
}
```

