    doc.font(font).fontSize(opts.bold ? 10 : 9);
    let maxH = 0;
    // measure each cell height
    const heights = cols.map((col, i) => {
      const txt = cells[i] ?? "";
      const h = doc.heightOfString(txt, { width: col.w - pad * 2 });
      return h;
    });
    maxH = Math.max(...heights) + pad * 2;
    // draw each cell
    cols.forEach((col, i) => {
      doc.text(cells[i] ?? "", col.x + pad, startY + pad, { width: col.w - pad * 2 });
    });
    doc.y = startY + maxH;
  };

  // header
  drawRow(cols.map(c => c.label), { bold: true });
  // underline
  const lineY = doc.y + 2;
