function buildStatementHtml(run) {
  const title = pageTitleOf(run);
  const date = fmtDate(run.createdAt ?? new Date().toISOString());
  const open = (run.questions || []).filter((q) => q.status === "open");
  const remaining = run.violationsAfter || [];

  const limitations = [];
  for (const q of open) {
    limitations.push({ hi: q.question, en: q.questionEnglish });
  }
  for (const v of remaining) {
    limitations.push({ hi: v.help || v.description, en: v.help || v.description });
  }

  const limItems = limitations
    .map((l) => {
      const en = l.en && l.en !== l.hi ? ` — ${l.en}` : "";
      return `<li>${escapeHtml(l.hi)}${escapeHtml(en)}</li>`;
